  "fi.features_earth_40m": "Dieselben Erdfenster mit 40 m (Mondauflösung)", "fi.features_earth_200m": "Dieselben Erdfenster mit 200 m (Mars-HRSC–MOLA-Auflösung)", "fi.features_earth_462m": "Dieselben Erdfenster mit etwa 463 m (Mars-MOLA-Auflösung)", "fi.modes_validation": "Validierung für jeden Testzweck und jedes Ziel", "fi.candidate_cards": "Ziel, türkischer Kandidat und Sentinel-2-Aufnahmedatum der Vergleichskarten", "fi.climate_earth": "Jahres- und Monatsklima jedes Standorts (NASA POWER)", "fi.ek_soilgrids": "SoilGrids-Werte je Punkt: Lagerungsdichte, Grobanteil, Ton, Sand", "fi.emit_library": "Einträge der EMIT-Mineralbibliothek, die für die Mineralprüfung genutzt wurden", "fi.fig.t": "Abbildungen", "fi.fig_moon_targets": "Mondziele", "fi.fig_mars_targets_200m": "Marsziele mit 200 m", "fi.fig_turkey_scan": "Karte der kahlen Flächen in der Türkei und Scan-Kandidaten", "fi.fig_candidate_cards": "Vergleichskarten: Ziel, türkischer Kandidat, Sentinel-2, WorldCover", "fi.fig_best_month": "Kalender des besten Testmonats", "fi.fig_modes": "Türkische Werte nach Testzweck", "fi.fig_robustness": "Robustheitstests", "fi.nb.t": "Notebook", "fi.nb": "das Google-Colab-Notebook, das alle Dateien dieser Seite erzeugt.", "fi.code": "Das Notebook und der Code dieser Seite liegen auch im GitHub-Repository des Projekts.",
